const MENU = {
  'nasi-goreng': { nama: 'Nasi Goreng Spesial', harga: 35000 },
  'mie-goreng': { nama: 'Mie Goreng Seafood', harga: 32000 },
  'ayam-bakar': { nama: 'Ayam Bakar Madu', harga: 42000 },
  'es-kopi-susu': { nama: 'Es Kopi Susu', harga: 22000 },
  'es-teh': { nama: 'Es Teh Manis', harga: 8000 }
};
const body = $input.first().json.body || {};
const items = Array.isArray(body.items) ? body.items : [];
const errors = [];
if (!body.pelanggan) errors.push('Nama pelanggan wajib diisi');
if (!['dine-in', 'takeaway', 'delivery'].includes(body.tipe)) errors.push('Tipe pesanan harus dine-in, takeaway, atau delivery');
if (body.tipe === 'dine-in' && !body.meja) errors.push('Nomor meja wajib untuk dine-in');
if (body.tipe === 'delivery' && !body.alamat) errors.push('Alamat wajib untuk delivery');
if (body.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(body.email)) errors.push('Format email tidak valid');
if (items.length === 0) errors.push('Item pesanan kosong');
let subtotal = 0;
const detail = [];
for (const it of items) {
  const m = MENU[it.kode];
  if (!m) { errors.push('Menu tidak dikenal: ' + it.kode); continue; }
  const qty = Number(it.qty) || 0;
  if (qty <= 0) { errors.push('Qty tidak valid untuk ' + it.kode); continue; }
  const total = m.harga * qty;
  subtotal += total;
  detail.push({ kode: it.kode, nama: m.nama, qty, harga: m.harga, total });
}
return [{ json: {
  order_id: 'FNB-' + Date.now(),
  waktu: new Date().toISOString(),
  pelanggan: body.pelanggan || null,
  email: body.email || null,
  tipe: body.tipe || null,
  meja: body.meja || null,
  alamat: body.alamat || null,
  catatan_pelanggan: body.catatan || '',
  kode_promo: String(body.kode_promo || '').toUpperCase(),
  member: body.member || 'none',
  jarak_km: Number(body.jarak_km) || 0,
  items: detail,
  subtotal,
  valid: errors.length === 0,
  errors
} }];

const o = $input.first().json;
const TIER = { none: 0, bronze: 0.05, silver: 0.10, gold: 0.15 };
const rate = TIER[o.member] ?? 0;
const diskon_member = Math.round(o.subtotal * rate);
const jam = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Jakarta' })).getHours();
const happy_hour = jam >= 14 && jam < 16;
const minuman = o.items.filter(i => ['es-kopi-susu', 'es-teh'].includes(i.kode)).reduce((s, i) => s + i.total, 0);
const diskon_happy_hour = happy_hour ? Math.round(minuman * 0.10) : 0;
let diskon_promo = 0;
let potongan_ongkir = 0;
let promo_info = null;
if (o.kode_promo) {
  if (o.kode_promo === 'HEMAT10' && o.subtotal >= 50000) {
    diskon_promo = Math.min(20000, Math.round(o.subtotal * 0.10));
    promo_info = 'HEMAT10 diterapkan';
  } else if (o.kode_promo === 'GRATISONGKIR' && o.tipe === 'delivery' && o.subtotal >= 75000) {
    potongan_ongkir = o.ongkir;
    promo_info = 'GRATISONGKIR diterapkan';
  } else {
    promo_info = 'Kode promo ' + o.kode_promo + ' tidak berlaku';
  }
}
const dpp = Math.max(0, o.subtotal - diskon_member - diskon_happy_hour - diskon_promo + o.biaya_layanan);
const pajak = Math.round(dpp * 0.10);
const ongkir_bayar = o.ongkir - potongan_ongkir;
const total_bayar = dpp + pajak + ongkir_bayar;
const poin_didapat = Math.floor(total_bayar / 10000);
return [{ json: { ...o, diskon_member, diskon_happy_hour, diskon_promo, potongan_ongkir, diskon: diskon_member + diskon_happy_hour + diskon_promo + potongan_ongkir, ongkir_bayar, promo_info, happy_hour, pajak, total_bayar, poin_didapat } }];

const data = $getWorkflowStaticData('global');
if (!data.stok) data.stok = { beras: 50, ayam: 40, mie: 40, kopi: 30, susu: 30, teh: 40 };
const RESEP = {
  'nasi-goreng': { beras: 1, ayam: 1 },
  'mie-goreng': { mie: 1, ayam: 1 },
  'ayam-bakar': { ayam: 2, beras: 1 },
  'es-kopi-susu': { kopi: 1, susu: 1 },
  'es-teh': { teh: 1 }
};
const o = $input.first().json;
const butuh = {};
for (const it of o.items) {
  for (const [b, q] of Object.entries(RESEP[it.kode] || {})) butuh[b] = (butuh[b] || 0) + q * it.qty;
}
const kurang = Object.entries(butuh).filter(([b, q]) => (data.stok[b] ?? 0) < q).map(([b]) => b);
let menipis = [];
if (kurang.length === 0) {
  for (const [b, q] of Object.entries(butuh)) data.stok[b] -= q;
  menipis = Object.entries(data.stok).filter(([b, q]) => q <= 10).map(([bahan, sisa]) => ({ bahan, sisa }));
}
return [{ json: { ...o, stok_cukup: kurang.length === 0, bahan_kurang: kurang, stok_menipis: menipis } }];

const data = $getWorkflowStaticData('global');
const o = $input.first().json;
if (!data.harian) data.harian = { omzet: 0, jumlah: 0, per_menu: {}, per_tipe: {} };
data.harian.omzet += o.total_bayar;
data.harian.jumlah += 1;
for (const it of o.items) data.harian.per_menu[it.nama] = (data.harian.per_menu[it.nama] || 0) + it.qty;
data.harian.per_tipe[o.tipe] = (data.harian.per_tipe[o.tipe] || 0) + 1;
if (!data.poin) data.poin = {};
const kunci = String(o.pelanggan || '').toLowerCase();
data.poin[kunci] = (data.poin[kunci] || 0) + o.poin_didapat;
return [{ json: { ...o, poin_total: data.poin[kunci] } }];

const o = $input.first().json;
const cfg = $('Konfigurasi Pesanan').first().json;
const rp = n => 'Rp' + String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const baris = o.items.map(i => '- ' + i.qty + 'x ' + i.nama + ' (' + rp(i.total) + ')').join('\n');
const lokasi = o.tipe === 'dine-in' ? 'Meja ' + o.meja : (o.tipe === 'delivery' ? 'Antar ke: ' + o.alamat : 'Ambil di kasir');
const pesan_dapur = 'PESANAN BARU ' + o.order_id + '\nPelanggan: ' + o.pelanggan + ' (member: ' + o.member + ')\nTipe: ' + o.tipe.toUpperCase() + ' - ' + lokasi + '\n\n' + baris + '\n\nCatatan: ' + (o.catatan_pelanggan || '-') + '\nEstimasi: ' + o.estimasi_menit + ' menit\nTotal: ' + rp(o.total_bayar);
const peringatan_restock = o.stok_menipis.length > 0 ? 'Segera restock: ' + o.stok_menipis.map(s => s.bahan + ' (sisa ' + s.sisa + ')').join(', ') : null;
const pesan_restock = peringatan_restock ? 'PERINGATAN STOK MENIPIS\n' + peringatan_restock + '\nTerpicu oleh pesanan ' + o.order_id : '';
const rows = o.items.map(i => `<tr><td>${esc(i.nama)}</td><td align='center'>${i.qty}</td><td align='right'>${rp(i.total)}</td></tr>`).join('');
const email_html = `<div style='font-family:Arial,sans-serif;max-width:480px;margin:auto'><h2>${esc(cfg.nama_toko)}</h2><p>Halo ${esc(o.pelanggan)}, terima kasih! Pesanan <b>${o.order_id}</b> sudah kami terima.</p><table width='100%' cellpadding='6' style='border-collapse:collapse'><tr style='background:#f3f3f3'><th align='left'>Menu</th><th>Qty</th><th align='right'>Harga</th></tr>${rows}</table><p>Subtotal: ${rp(o.subtotal)}<br>Diskon: -${rp(o.diskon)}<br>Biaya layanan: ${rp(o.biaya_layanan)}<br>Ongkir: ${rp(o.ongkir_bayar)}<br>Pajak 10%: ${rp(o.pajak)}<br><b>Total: ${rp(o.total_bayar)}</b></p><p>Estimasi: ${o.estimasi_menit} menit. Poin didapat: ${o.poin_didapat} (total ${o.poin_total}).</p></div>`;
const email_subject = 'Struk Pesanan ' + o.order_id + ' - ' + cfg.nama_toko;
const row = {
  order_id: o.order_id,
  waktu: o.waktu,
  pelanggan: o.pelanggan,
  tipe: o.tipe,
  member: o.member,
  item: o.items.map(i => i.qty + 'x ' + i.nama).join('; '),
  subtotal: o.subtotal,
  diskon: o.diskon,
  promo: o.promo_info || '',
  biaya_layanan: o.biaya_layanan,
  ongkir: o.ongkir_bayar,
  pajak: o.pajak,
  total_bayar: o.total_bayar,
  poin: o.poin_didapat,
  status: 'diterima'
};
return [{ json: { ...o, pesan_dapur, pesan_restock, peringatan_restock, email_subject, email_html, row } }];

const data = $getWorkflowStaticData('global');
const stok = data.stok || { beras: 50, ayam: 40, mie: 40, kopi: 30, susu: 30, teh: 40 };
const h = data.harian || { omzet: 0, jumlah: 0, per_menu: {}, per_tipe: {} };
const rp = n => 'Rp' + String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const kritis = Object.entries(stok).filter(([b, q]) => q <= 10).map(([bahan, sisa]) => ({ bahan, sisa }));
const terlaris = Object.entries(h.per_menu).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([n, q]) => n + ' (' + q + ')');
const tanggal = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Jakarta' });
const rata = h.jumlah ? Math.round(h.omzet / h.jumlah) : 0;
const per_tipe = Object.entries(h.per_tipe).map(([t, n]) => t + ': ' + n).join(', ') || '-';
const laporan = 'LAPORAN HARIAN ' + tanggal + '\nOmzet: ' + rp(h.omzet) + '\nJumlah pesanan: ' + h.jumlah + '\nRata-rata per pesanan: ' + rp(rata) + '\nPer tipe: ' + per_tipe + '\nMenu terlaris: ' + (terlaris.join(', ') || '-') + '\nStok kritis: ' + (kritis.map(k => k.bahan + ' (' + k.sisa + ')').join(', ') || 'tidak ada');
data.harian = { omzet: 0, jumlah: 0, per_menu: {}, per_tipe: {} };
return [{ json: { tanggal, omzet: h.omzet, jumlah_pesanan: h.jumlah, rata_rata: rata, terlaris, stok, kritis, ada_kritis: kritis.length > 0, laporan } }];

const o = $input.first().json;
return [{ json: {
  tanggal: o.tanggal,
  omzet: o.omzet,
  jumlah_pesanan: o.jumlah_pesanan,
  rata_rata: o.rata_rata,
  menu_terlaris: o.terlaris.join('; '),
  stok_kritis: o.kritis.map(k => k.bahan + ' (' + k.sisa + ')').join('; ')
} }];

