const data = $getWorkflowStaticData('global');
const stok = data.stok || { beras: 50, ayam: 40, mie: 40, kopi: 30, susu: 30, teh: 40 };
const status = Object.entries(stok).map(([bahan, sisa]) => ({ bahan, sisa, status: sisa <= 10 ? 'kritis' : (sisa <= 20 ? 'rendah' : 'aman') }));
return [{ json: { stok, status } }];

const data = $getWorkflowStaticData('global');
if (!data.stok) data.stok = { beras: 50, ayam: 40, mie: 40, kopi: 30, susu: 30, teh: 40 };
const b = $input.first().json.body || {};
const jumlah = Number(b.jumlah);
if (!(b.bahan in data.stok)) return [{ json: { ok: false, pesan: 'Bahan tidak dikenal: ' + b.bahan, bahan_tersedia: Object.keys(data.stok) } }];
if (!(jumlah > 0)) return [{ json: { ok: false, pesan: 'Jumlah harus lebih dari 0' } }];
data.stok[b.bahan] += jumlah;
return [{ json: { ok: true, pesan: 'Stok ' + b.bahan + ' ditambah ' + jumlah, stok_sekarang: data.stok } }];
